    uiVersion: []const u8 = "",
    kernelVersion: []const u8 = "",
    OSVersion: []const u8 = "",
    networkAddresses: []NetworkAddress = &.{},
    sysSerialNumber: []const u8 = "",
    sysProductName: []const u8 = "",
    sysManufacturer: []const u8 = "",
    environment: ?Environment = null,
    files: []File = &.{},
    flags: ?Flags = null,
    capabilities: []PeerCapability = &.{},
    syncMessageVersion: i32 = 0,
    unknown_fields: []const u8 = &.{},

pub fn size(m: *const @This()) usize {
    var n: usize = 0;
    if ((m.hostname.len != 0)) n += wire.sizeTag(1) + wire.sizeBytes(m.hostname.len);
    if ((m.goOS.len != 0)) n += wire.sizeTag(2) + wire.sizeBytes(m.goOS.len);
    if ((m.kernel.len != 0)) n += wire.sizeTag(3) + wire.sizeBytes(m.kernel.len);
    if ((m.core.len != 0)) n += wire.sizeTag(4) + wire.sizeBytes(m.core.len);
    if ((m.platform.len != 0)) n += wire.sizeTag(5) + wire.sizeBytes(m.platform.len);
    if ((m.OS.len != 0)) n += wire.sizeTag(6) + wire.sizeBytes(m.OS.len);
    if ((m.netbirdVersion.len != 0)) n += wire.sizeTag(7) + wire.sizeBytes(m.netbirdVersion.len);
    if ((m.uiVersion.len != 0)) n += wire.sizeTag(8) + wire.sizeBytes(m.uiVersion.len);
    if ((m.kernelVersion.len != 0)) n += wire.sizeTag(9) + wire.sizeBytes(m.kernelVersion.len);
    if ((m.OSVersion.len != 0)) n += wire.sizeTag(10) + wire.sizeBytes(m.OSVersion.len);
    for (m.networkAddresses) |*el| n += wire.sizeTag(11) + wire.sizeBytes(el.size());
    if ((m.sysSerialNumber.len != 0)) n += wire.sizeTag(12) + wire.sizeBytes(m.sysSerialNumber.len);
    if ((m.sysProductName.len != 0)) n += wire.sizeTag(13) + wire.sizeBytes(m.sysProductName.len);
    if ((m.sysManufacturer.len != 0)) n += wire.sizeTag(14) + wire.sizeBytes(m.sysManufacturer.len);
    if (m.environment) |c| n += wire.sizeTag(15) + wire.sizeBytes(c.size());
    for (m.files) |*el| n += wire.sizeTag(16) + wire.sizeBytes(el.size());
    if (m.flags) |c| n += wire.sizeTag(17) + wire.sizeBytes(c.size());
    if (m.capabilities.len != 0) {
        var payload: usize = 0;
        for (m.capabilities) |el| payload += wire.sizeVarint(@as(u64, @bitCast(@as(i64, @intFromEnum(el)))));
        n += wire.sizeTag(18) + wire.sizeVarint(payload) + payload;
    }
    if ((m.syncMessageVersion != 0)) n += wire.sizeTag(19) + wire.sizeVarint(@as(u64, @bitCast(@as(i64, m.syncMessageVersion))));
    return n + m.unknown_fields.len;
}

