    if ((m.translatedAddress.len != 0)) n += wire.sizeTag(3) + wire.sizeBytes(m.translatedAddress.len);
    if (m.translatedPort) |c| n += wire.sizeTag(4) + wire.sizeBytes(c.size());
    return n + m.unknown_fields.len;
}

