                    if (old.* == .delta) { try old.delta.mergeWithDepth(a, b, depth - 1); continue; }
                }
                const child = try NetworkMapComponentsDelta.decodeWithDepth(a, b, depth - 1);
                if (m.payload) |*old| switch (old.*) {
                    .full => |*previous_child| previous_child.deinit(a),
                    .delta => |*previous_child| previous_child.deinit(a),
                };
                m.payload = null;
                m.payload = .{ .delta = child };
            } else {
                _ = try d.skipField(tag.num, tag.typ); var tb: [10]u8 = undefined; var te = wire.Encoder.init(&tb); try te.appendTag(tag.num, tag.typ); try unknown.appendSlice(a, tb[0..te.len]); try unknown.appendSlice(a, buf[tag_end..d.pos]);
            },
