    for (m.account_zones) |*el| n += wire.sizeTag(16) + wire.sizeBytes(el.size());
    for (m.network_resources) |*el| n += wire.sizeTag(17) + wire.sizeBytes(el.size());
    for (m.routers_map) |*en| {
