        if (en.key.len != 0) esz += wire.sizeTag(1) + wire.sizeBytes(en.key.len);
        esz += wire.sizeTag(2) + wire.sizeBytes(en.value.size());
        n += wire.sizeTag(18) + wire.sizeBytes(esz);
    }
    for (m.resource_policies_map) |*en| {
