        try e.appendTag(15, .bytes);
        try e.appendVarint(sz);
        try el.encode(e.buf[e.len..][0..sz]);
        e.len += sz;
    }
    for (m.account_zones) |*el| {
        const sz = el.size();
        try e.appendTag(16, .bytes);
        try e.appendVarint(sz);
        try el.encode(e.buf[e.len..][0..sz]);
