        const sz = el.size();
        try e.appendTag(17, .bytes);
        try e.appendVarint(sz);
        try el.encode(e.buf[e.len..][0..sz]);
        e.len += sz;
    }
    {
    var previous_entry: ?*const routers_map_Entry = null;
    while (true) {
        var next_entry: ?*const routers_map_Entry = null;
        for (m.routers_map) |*candidate| {
            if (previous_entry) |previous| if (!(std.mem.order(u8, candidate.key, previous.key) == .gt)) continue;
