pub fn decode(a: std.mem.Allocator, buf: []const u8) DecodeError!@This() {
    return @This().decodeWithDepth(a, buf, default_recursion_depth);
}

pub fn decodeWithDepth(a: std.mem.Allocator, buf: []const u8, depth: u32) DecodeError!@This() {
    if (depth == 0) return error.RecursionDepth;
    var m = @This(){};
    errdefer m.deinit(a);
    try m.mergeWithDepth(a, buf, depth);
    return m;
}
pub fn mergeWithDepth(m: *@This(), a: std.mem.Allocator, buf: []const u8, depth: u32) DecodeError!void {
    if (depth == 0) return error.RecursionDepth;
    var unknown: std.ArrayList(u8) = .{ .items = @constCast(m.unknown_fields), .capacity = m.unknown_fields.len, .pointer_stability = .{} };
    m.unknown_fields = &.{};
    defer unknown.deinit(a);
    var d = wire.Decoder.init(buf);
    var list_user_ids: std.ArrayList([]const u8) = .empty;
    list_user_ids = .{ .items = m.user_ids, .capacity = m.user_ids.len, .pointer_stability = .{} };
    m.user_ids = &.{};
    errdefer list_user_ids.deinit(a);
    errdefer for (list_user_ids.items) |v| if (v.len != 0) a.free(v);
    while (!d.done()) {
        const tag = try d.consumeTag();
        const tag_end = d.pos;
        switch (tag.num) {
            1 => if (tag.typ == .bytes) {
                const b = try d.consumeBytes();
                const owned = a.dupe(u8, b) catch return error.OutOfMemory;
                errdefer a.free(owned);
                try list_user_ids.append(a, owned);
            } else {
                            _ = try d.skipField(tag.num, tag.typ); var tb: [10]u8 = undefined; var te = wire.Encoder.init(&tb); try te.appendTag(tag.num, tag.typ); try unknown.appendSlice(a, tb[0..te.len]); try unknown.appendSlice(a, buf[tag_end..d.pos]);
            },
            else => {
                _ = try d.skipField(tag.num, tag.typ);
                var tb: [10]u8 = undefined; var te = wire.Encoder.init(&tb); try te.appendTag(tag.num, tag.typ); try unknown.appendSlice(a, tb[0..te.len]); try unknown.appendSlice(a, buf[tag_end..d.pos]);
            },
        }
    }
    m.user_ids = list_user_ids.toOwnedSlice(a) catch return error.OutOfMemory;
    m.unknown_fields = try unknown.toOwnedSlice(a);
}

pub fn deinit(m: *@This(), a: std.mem.Allocator) void {
    for (m.user_ids) |s| if (s.len != 0) a.free(s);
    if (m.user_ids.len != 0) a.free(m.user_ids);
    if (m.unknown_fields.len != 0) a.free(m.unknown_fields);
}
};

pub const PeerIndexSet = struct {
    peer_indexes: []u32 = &.{},
    unknown_fields: []const u8 = &.{},

pub fn size(m: *const @This()) usize {
    var n: usize = 0;
    if (m.peer_indexes.len != 0) {
        var payload: usize = 0;
        for (m.peer_indexes) |el| payload += wire.sizeVarint(@as(u64, el));
        n += wire.sizeTag(1) + wire.sizeVarint(payload) + payload;
    }
    return n + m.unknown_fields.len;
}

pub fn encode(m: *const @This(), out: []u8) wire.Error!void {
    var e = wire.Encoder.init(out);
    if (m.peer_indexes.len != 0) {
        var payload: usize = 0;
        for (m.peer_indexes) |el| payload += wire.sizeVarint(@as(u64, el));
        try e.appendTag(1, .bytes);
        try e.appendVarint(payload);
        for (m.peer_indexes) |el| try e.appendVarint(@as(u64, el));
    }
    if (m.unknown_fields.len > e.buf.len - e.len) return error.NoSpaceLeft;
    @memcpy(e.buf[e.len..][0..m.unknown_fields.len], m.unknown_fields);
    e.len += m.unknown_fields.len;
}

pub fn decode(a: std.mem.Allocator, buf: []const u8) DecodeError!@This() {
    return @This().decodeWithDepth(a, buf, default_recursion_depth);
}

pub fn decodeWithDepth(a: std.mem.Allocator, buf: []const u8, depth: u32) DecodeError!@This() {
    if (depth == 0) return error.RecursionDepth;
    var m = @This(){};
    errdefer m.deinit(a);
    try m.mergeWithDepth(a, buf, depth);
    return m;
}
pub fn mergeWithDepth(m: *@This(), a: std.mem.Allocator, buf: []const u8, depth: u32) DecodeError!void {
    if (depth == 0) return error.RecursionDepth;
    var unknown: std.ArrayList(u8) = .{ .items = @constCast(m.unknown_fields), .capacity = m.unknown_fields.len, .pointer_stability = .{} };
    m.unknown_fields = &.{};
    defer unknown.deinit(a);
    var d = wire.Decoder.init(buf);
    var list_peer_indexes: std.ArrayList(u32) = .empty;
    list_peer_indexes = .{ .items = m.peer_indexes, .capacity = m.peer_indexes.len, .pointer_stability = .{} };
    m.peer_indexes = &.{};
    errdefer list_peer_indexes.deinit(a);
    while (!d.done()) {
        const tag = try d.consumeTag();
        const tag_end = d.pos;
        switch (tag.num) {
            1 => switch (tag.typ) {
                .bytes => {
                    const pb = try d.consumeBytes();
                    var pd = wire.Decoder.init(pb);
                    while (!pd.done()) {
                        const el = blk: { const v = try pd.consumeVarint(); break :blk @as(u32, @truncate(v)); };
                        try list_peer_indexes.append(a, el);
                    }
                },
                .varint => {
                    const el = blk: { const v = try d.consumeVarint(); break :blk @as(u32, @truncate(v)); };
                    try list_peer_indexes.append(a, el);
                },
                else => {
                    _ = try d.skipField(tag.num, tag.typ); var tb: [10]u8 = undefined; var te = wire.Encoder.init(&tb); try te.appendTag(tag.num, tag.typ); try unknown.appendSlice(a, tb[0..te.len]); try unknown.appendSlice(a, buf[tag_end..d.pos]);
                },
            },
            else => {
                _ = try d.skipField(tag.num, tag.typ);
                var tb: [10]u8 = undefined; var te = wire.Encoder.init(&tb); try te.appendTag(tag.num, tag.typ); try unknown.appendSlice(a, tb[0..te.len]); try unknown.appendSlice(a, buf[tag_end..d.pos]);
            },
        }
    }
    m.peer_indexes = list_peer_indexes.toOwnedSlice(a) catch return error.OutOfMemory;
    m.unknown_fields = try unknown.toOwnedSlice(a);
}

pub fn deinit(m: *@This(), a: std.mem.Allocator) void {
    if (m.peer_indexes.len != 0) a.free(m.peer_indexes);
    if (m.unknown_fields.len != 0) a.free(m.unknown_fields);
}
};
